  const {
  name, count, mode, show, items, label, value, custom,
  settings, context, locales, amount, date
} = props;
  return (<main><h1>Account {name}</h1><Subject >{(() => <p>Computed {name}</p>)()}</Subject><footer>Next</footer></main>);
}

